    private void editarSignos(SignosVitales x) { ConfiguracionEmpresaFase2 c=unidades(); BigDecimalField peso=new BigDecimalField("Peso ("+("LIBRAS".equals(c.getUnidadPeso())?"lb":"kg")+")"), altura=new BigDecimalField("Altura ("+("PIES".equals(c.getUnidadAltura())?"pies":"m")+")"), temp=new BigDecimalField("Temperatura (°"+c.getUnidadTemperatura()+")"), saturacion=new BigDecimalField("Saturación SpO₂ (%)"), glucemia=new BigDecimalField("Glucemia (mg/dL)"), abdomen=new BigDecimalField("Circunferencia abdominal (cm)"); IntegerField sis=new IntegerField("Presión sistólica"), dia=new IntegerField("Presión diastólica"), pulso=new IntegerField("Pulso (lpm)"), respiratoria=new IntegerField("Frecuencia respiratoria (rpm)"), dolor=new IntegerField("Nivel de dolor (0–10)"); TextArea observaciones=new TextArea("Observaciones"); peso.setValue(desdeKg(x.getPeso(),c)); altura.setValue(desdeMetros(x.getAltura(),c)); temp.setValue(desdeCelsius(x.getTemperatura(),c)); saturacion.setValue(x.getSaturacionOxigeno()); glucemia.setValue(x.getGlucemia()); abdomen.setValue(x.getCircunferenciaAbdominal()); sis.setValue(x.getPresionSistolica()); dia.setValue(x.getPresionDiastolica()); pulso.setValue(x.getFrecuenciaCardiaca()); respiratoria.setValue(x.getFrecuenciaRespiratoria()); dolor.setValue(x.getNivelDolor()); observaciones.setValue(x.getObservaciones()==null?"":x.getObservaciones()); dialogo("Editar signos vitales", formularioTresColumnas(peso,altura,temp,sis,dia,pulso,respiratoria,saturacion,glucemia,abdomen,dolor,observaciones), () -> signosVitales.actualizarCompleto(empresaId,x.getId(),aKg(peso.getValue(),c),aMetros(altura.getValue(),c),aCelsius(temp.getValue(),c),sis.getValue(),dia.getValue(),pulso.getValue(),respiratoria.getValue(),saturacion.getValue(),glucemia.getValue(),abdomen.getValue(),dolor.getValue(),observaciones.getValue())); }
